import { Link } from "react-router-dom";

const Dummy_Event = [
    {
        id: 'el',
        title: 'Some event',
    },
    {
        id: 'e2',
        title: 'another event',
    },
    {
        id: 'e3',
        title: ' up comming event'
    },
];


function EventPage()
{
    return (
        <>
        <h1>Event Page</h1>
        <ul>
            {Dummy_Event.map((event) => (
                <li key={event.id}> <Link to={event.id}>{event.title}</Link></li>
            ))}
        </ul>
        </>
    )
}

export default EventPage;
